/* ---------- Details panel ---------- */
.dtp{padding:12px;display:flex;flex-direction:column;gap:6px}
.dtp-h{display:flex;align-items:center;gap:8px;padding:2px 4px 6px;font-size:13.5px}
.dtp-h b{font-weight:500;flex:1;min-width:0}
.dtp-sh{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted);padding:6px 4px;width:100%;text-align:left}
.dtp-sh:hover{color:var(--fg)}
.dtp-sh svg{transition:transform .4s var(--ease);transform:rotate(90deg)}
.dtp-sh[aria-expanded="false"] svg{transform:none}
.dtp-rows{display:flex;flex-direction:column}
.dtp-r{display:grid;grid-template-columns:84px 1fr;align-items:center;min-height:34px;font-size:13px;position:relative}
.dtp-r .k{color:var(--muted);padding-left:4px}
.dtp-v{display:inline-flex;align-items:center;gap:7px;justify-self:start;height:28px;padding:0 8px;margin-left:-8px;border-radius:8px;transition:background .2s;color:var(--fg)}
:where([data-c]) button.dtp-v:hover,:where([data-c]) button.dtp-v[aria-expanded="true"]{background:var(--chip)}
.dtp-v .av{width:20px;height:20px;font-size:9.5px}
.dtp-v>svg{color:var(--muted)}
.dtp-v.flash{animation:dtpf .9s var(--ease)}
@keyframes dtpf{30%{background:var(--accent-bg)}}
.dtp-tags{display:flex;gap:4px;align-items:center;flex-wrap:wrap}
.dtp-add{width:20px;height:20px;border-radius:6px;display:grid;place-items:center;color:var(--muted);box-shadow:inset 0 0 0 1px var(--line)}
.dtp-add:hover{color:var(--fg);background:var(--chip)}
.dtp .mi .av{width:20px;height:20px;font-size:9.5px}
.dtp .pop{min-width:180px}

DM.def('details-panel', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{link}', I('link','xs')).replace(/\{chev\}/g, I('chev-r','xs')).replace('{chevd}', I('chev-d','xs')).replace('{plus}', I('plus','xs'))
    .replace(/\{avm\}/g, AV('MK','var(--pl)')).replace('{avj}', AV('JO','var(--pm)')).replace('{ava}', AV('DA','var(--pb)'));
  const flash = el => { el.classList.remove('flash'); void el.offsetWidth; el.classList.add('flash'); };
  $$('.pop', r).forEach(pp => $('.dtp', r).appendChild(pp));
  $$('.dtp-sh', r).forEach(b => b.onclick = () => { const f = b.nextElementSibling, open = f.classList.toggle('shut') === false; b.setAttribute('aria-expanded', open); });
  $$('.dtp-pst .mi', r).forEach(m => m.addEventListener('click', () => { const v = $('.dtp-stat', r); $('.dot', v).style.color = m.dataset.c; swap($('span:last-child', v), m.dataset.s); flash(v); }));
  $$('.dtp-pow .mi', r).forEach(m => m.addEventListener('click', () => { const v = $('.dtp-own', r); const av = $('.av', v); av.textContent = m.dataset.i; av.style.background = m.dataset.c; enter(av); swap($('span:last-child', v), m.dataset.o); flash(v); }));
  const cost = { Opus:[184200, 2.76], Sonnet:[184200, .55], Haiku:[184200, .15] }; let cc = 0, ct = 0;
  const setM = m => { tween(ct, cost[m][0], 800, v => { ct = v; $('.dtp-tok', r).textContent = Math.round(v).toLocaleString('en-US'); }); tween(cc, cost[m][1], 800, v => { cc = v; $('.dtp-cost', r).textContent = '$' + v.toFixed(2); }); };
  $$('.dtp-pmo .mi', r).forEach(m => m.addEventListener('click', () => { const v = $('.dtp-mo', r); swap(v, m.dataset.m); flash(v.parentElement); setM(m.dataset.m); }));
  const labels = [['Q4','y'],['A/B test','t'],['Urgent','r']]; let li = 0;
  $('.dtp-add', r).onclick = e => { if (li >= labels.length) return; const t = html(`<span class="tag ${labels[li][1]}">${labels[li][0]}</span>`); e.currentTarget.before(t); enter(t); li++; };
  const cp = $('.dtp-cp', r); cp.onclick = () => copied(cp, 'run_8f2a');
  c.later(400, () => setM('Opus'));
});
